begin;
do $$
declare e uuid; application uuid; application2 uuid; ambassador uuid; admin_id uuid; v_email text:='apply-'||gen_random_uuid()||'@example.test'; rejected boolean; before_codes integer;
begin
 select id into e from public.events where slug='halloween-party-2026';
 select count(*) into before_codes from public.ambassador_codes;
 rejected:=false;begin perform public.submit_campus_interest(e,'Demo Leader','Demo Campus',v_email,'01000000000',false);exception when others then rejected:=true;end;
 assert rejected,'Privacy consent is required';
 perform public.submit_campus_interest(e,'Demo Leader','Demo Campus',v_email,'01000000000',true);
 perform public.submit_campus_interest(e,'Attempted overwrite','Another Campus',upper(v_email),'01000000001',true);
 select id into application from public.campus_ambassador_applications a where a.event_id=e and a.email=v_email;
 assert application is not null,'Application must be saved';
 assert (select count(*) from public.campus_ambassador_applications where event_id=e and email=v_email)=1,'Duplicate email must not create another request';
 assert (select full_name from public.campus_ambassador_applications where id=application)='Demo Leader','Public retries must not overwrite private details';
 assert (select count(*) from public.ambassador_codes)=before_codes,'Applying must never create a code';
 perform set_config('request.jwt.claim.sub','',true);
 rejected:=false;begin perform public.review_campus_application(application,true,'APPLYTEST');exception when others then rejected:=true;end;
 assert rejected,'Only an admin may approve';
 select id into admin_id from public.admin_users where is_active and role='admin' limit 1;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 ambassador:=public.review_campus_application(application,true,'APPLYTEST-D1');
 assert ambassador is not null,'Approval creates an ambassador';
 assert ambassador=public.review_campus_application(application,true,'APPLYTEST-D1'),'Approval retries must not duplicate ambassadors';
 assert (select code from public.ambassador_codes where ambassador_id=ambassador and is_active)='APPLYTEST-D1','Approval must preserve the exact code chosen by the owner';
 assert (select status from public.campus_ambassador_applications where id=application)='approved','Review status must persist';
 assert (select count(*) from public.ambassador_codes where ambassador_id=ambassador and is_active)=1,'Approval creates exactly one active code';
 assert (select email from public.campus_ambassadors where id=ambassador)=v_email,'Contact details transfer from the application';
 perform public.submit_campus_interest(e,'Second Demo Leader','Demo Campus','second-'||v_email,'01000000002',true);
 select id into application2 from public.campus_ambassador_applications where email='second-'||v_email;
 perform public.review_campus_application(application2,false,null);
 assert (select status from public.campus_ambassador_applications where id=application2)='rejected','Rejection must be recorded';
 assert (select ambassador_id from public.campus_ambassador_applications where id=application2) is null,'Rejected applications must not activate an ambassador';
 rejected:=false;begin perform public.submit_requested_campus_interest(e,'Code Leader','Demo University','code-'||v_email,'01000000003',true,'AUC','GUC-D1');exception when others then rejected:=true;end;
 assert rejected,'Wrong university prefix must fail';
 rejected:=false;begin perform public.submit_requested_campus_interest(e,'Code Leader','Demo University','code-'||v_email,'01000000003',true,'12','12-D1');exception when others then rejected:=true;end;
 assert rejected,'University abbreviation must contain letters only';
 perform public.submit_requested_campus_interest(e,'Code Leader','Demo University','code-'||v_email,'01000000003',true,'auc','auc-requesttest');
 select id into application2 from public.campus_ambassador_applications where email='code-'||v_email;
 assert (select requested_code from public.campus_ambassador_applications where id=application2)='AUC-REQUESTTEST','Requested code is stored uppercase';
 perform public.submit_requested_campus_interest(e,'Different Leader','Other University','code-'||v_email,'01000000004',true,'GUC','GUC-D2');
 assert (select requested_code from public.campus_ambassador_applications where id=application2)='AUC-REQUESTTEST','Duplicate submission must not overwrite code';
 rejected:=false;begin perform public.review_campus_application(application2,true,'GUC-REQUESTTEST');exception when others then rejected:=true;end;
 assert rejected,'Admin approval must preserve university prefix';
 ambassador:=public.review_campus_application(application2,true,'AUC-REQUESTTEST');
 assert (select code from public.ambassador_codes where ambassador_id=ambassador and is_active)='AUC-REQUESTTEST','Requested code activates only on approval';
 perform public.submit_requested_campus_interest(e,'Duplicate Code Leader','Demo University','duplicate-'||v_email,'01000000005',true,'AUC','AUC-REQUESTTEST');
 select id into application2 from public.campus_ambassador_applications where email='duplicate-'||v_email;
 rejected:=false;begin perform public.review_campus_application(application2,true,'AUC-REQUESTTEST');exception when others then rejected:=true;end;
 assert rejected,'An active code must not be reassigned';
 assert (select status from public.campus_ambassador_applications where id=application2)='pending','Failed activation leaves application pending';
 assert not has_function_privilege('anon','public.submit_requested_campus_interest(uuid,text,text,text,text,boolean,text,text)','execute'),'Requested-code writes are server only';
 perform set_config('request.jwt.claim.sub','',true);
 application:=gen_random_uuid();
 assert public.register_campus_leader(e,'Automatic Leader','Demo University','automatic-'||v_email,'01000000006',true,'AUC','AUC-AUTOTEST',application)=application,'Registration returns only the new private token';
 assert (select status from public.campus_ambassador_applications where tracking_token=application)='approved','Self registration is immediately active without admin approval';
 select ambassador_id into ambassador from public.campus_ambassador_applications where tracking_token=application;
 assert (select code from public.ambassador_codes where ambassador_id=ambassador and is_active)='AUC-AUTOTEST','An active chosen code is created automatically';
 assert public.register_campus_leader(e,'Automatic Leader','Demo University','automatic-'||v_email,'01000000006',true,'AUC','AUC-AUTOTEST',application)=application,'Retry with private token is idempotent';
 rejected:=false;begin perform public.register_campus_leader(e,'Impersonation','Demo University','automatic-'||v_email,'01000000006',true,'AUC','AUC-DIFFERENT',gen_random_uuid());exception when others then rejected:=true;end;
 assert rejected,'Email-only retry must never reveal another leader private link';
 rejected:=false;begin perform public.register_campus_leader(e,'Another Leader','Demo University','code-duplicate-'||v_email,'01000000006',true,'AUC','AUC-AUTOTEST',gen_random_uuid());exception when others then rejected:=true;end;
 assert rejected,'Automatic registration must reject an assigned code';
 assert not exists(select 1 from public.campus_ambassadors where email='code-duplicate-'||v_email),'Failed registration must not leave partial leaders';
 rejected:=false;begin perform public.register_campus_leader(e,'Wrong Prefix','Demo University','wrong-'||v_email,'01000000006',true,'AUC','GUC-AUTOTEST',gen_random_uuid());exception when others then rejected:=true;end;
 assert rejected,'Automatic code must have the university prefix';
 assert not has_function_privilege('anon','public.register_campus_leader(uuid,text,text,text,text,boolean,text,text,uuid)','execute'),'Automatic registration is callable only through validating server';
 assert not has_table_privilege('anon','public.campus_ambassador_applications','select'),'Applicants must not read private requests';
 assert not has_function_privilege('anon','public.submit_campus_interest(uuid,text,text,text,text,boolean)','execute'),'Public writes must pass through the validating server';
 raise notice 'PASS: consent, duplicate protection, no code before approval, admin authorization, idempotent approval and rejection';
end $$;
rollback;
